er=androidx.compose.foundation.BorderStroke(4.dp,Color(0xFFF87171)),shadowElevation=7.dp){Column(horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("🛒 РАСХОДЫ",fontSize=14.sp,fontWeight=FontWeight.Black,color=Color(0xFFB91C1C));Text("${s.expenses} монет",fontSize=16.sp,fontWeight=FontWeight.Black);Text(if(selected!=null)"Отпусти здесь" else "Деньги уходят",fontSize=9.sp,color=Color(0xFF64748B))}}}}
    }
    if(s.cards.isNotEmpty()){Text("КОЛОДА • зажми и перетащи на весы",fontSize=13.sp,fontWeight=FontWeight.Black,color=Color(0xFF263A65));LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp),contentPadding=PaddingValues(vertical=4.dp)){items(s.cards,key={it.id}){card->val active=card.id==selectedId;var drag by remember(card.id){mutableStateOf(Offset.Zero)};var origin by remember(card.id){mutableStateOf(Offset.Zero)};var size by remember(card.id){mutableStateOf(androidx.compose.ui.unit.IntSize.Zero)};val dragging=drag!=Offset.Zero;Surface(Modifier.width(92.dp).height(100.dp).zIndex(if(dragging)20f else 0f).graphicsLayer{translationX=drag.x;translationY=drag.y;scaleX=if(dragging)1.08f else 1f;scaleY=if(dragging)1.08f else 1f;shadowElevation=if(dragging)24f else 0f}.onGloballyPositioned{origin=it.boundsInRoot().topLeft;size=it.size}.pointerInput(card.id){detectDragGesturesAfterLongPress(onDragStart={selectedId=card.id},onDrag={change,amount->change.consume();drag+=amount},onDragCancel={drag=Offset.Zero},onDragEnd={val center=origin+drag+Offset(size.width/2f,size.height/2f);when{incomeBounds.contains(center)->vm.place(card,true);expenseBounds.contains(center)->vm.place(card,false)};selectedId=null;drag=Offset.Zero})}.clickable{selectedId=card.id},shape=RoundedCornerShape(16.dp),color=if(active)Color(0xFFFFF0B5)else Color.White,border=androidx.compose.foundation.BorderStroke(if(active)4.dp else 1.dp,if(active)Color(0xFFF59E0B)else Color(0xFFD6DFEC)),shadowElevation=5.dp){Column(Modifier.padding(6.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.SpaceEvenly){Text(when(card.id){"work"->"💼";"reward"->"🏆";"gift"->"🎁";"food"->"🍗";"rent"->"🏠";"transport"->"🚌";"medicine"->"❤";"toy"->"🧸";else->"★"},fontSize=25.sp);Text(card.title,fontSize=10.sp,fontWeight=FontWeight.Bold,textAlign=androidx.compose.ui.text.style.TextAlign.Center,maxLines=2);Text("${card.amount} мон.",fontSize=12.sp,fontWeight=FontWeight.Black,color=Color(0xFF263A65))}}}}
        FinnySpeechCard(if(selected==null)"Зажми карточку и перетащи её: доход — на левую чашу, расход — на правую." else "Куда относится «${selected.title}»: деньги приходят или уходят?")
    }else{FinnySpeechCard("Все карточки на месте, а баланс не ушёл в минус. Подводим итог…")}
}}

@Composable fun PrioritiesScreen(onBack:()->Unit,onDone:(Int)->Unit,vm:PrioritiesViewModel=hiltViewModel()){val s by vm.state.collectAsStateWithLifecycle();if(s.message.isNotEmpty()&&s.message!="Хороший выбор!")FeedbackDialog("Почему так?",s.message,vm::clearMessage);val card=s.cards.firstOrNull();var nowBounds by remember{mutableStateOf(Rect.Zero)};var laterBounds by remember{mutableStateOf(Rect.Zero)};var noBounds by remember{mutableStateOf(Rect.Zero)};var drag by remember(card?.id){mutableStateOf(Offset.Zero)};var cardOrigin by remember(card?.id){mutableStateOf(Offset.Zero)};var cardSize by remember(card?.id){mutableStateOf(androidx.compose.ui.unit.IntSize.Zero)};GameFrame("Приоритеты","Перетаскивай покупки в нужный контейнер",s.level,onBack){
    LaunchedEffect(s.cards.isEmpty()){if(s.cards.isEmpty()){kotlinx.coroutines.delay(650);vm.finish(onDone)}}
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){GameStat("₽","Бюджет",s.budget.toString(),Color(0xFFFFF0C9),Modifier.weight(1f));GameStat("✓","Запланировано",s.placed.toString(),Color(0xFFE6F0FF),Modifier.weight(1f));GameStat("=","Свободно",(s.budget-s.placed).toString(),Color(0xFFDFF7EB),Modifier.weight(1f))}
