            listOf(
                PriorityZone.NOW to Triple(Icons.Default.CheckCircle,"Сейчас",Color(0xFF43AD75)),
                PriorityZone.LATER to Triple(Icons.Default.Schedule,"Потом",Color(0xFFE9A437)),
                PriorityZone.NO to Triple(Icons.Default.Block,"Пропустить",Color(0xFFE45F68))
            ).forEach{(zone,style)->Surface(Modifier.weight(1f).height(103.dp).onGloballyPositioned{when(zone){PriorityZone.NOW->nowBounds=it.boundsInRoot();PriorityZone.LATER->laterBounds=it.boundsInRoot();PriorityZone.NO->noBounds=it.boundsInRoot()}}.clickable{vm.place(card,zone)},shape=RoundedCornerShape(20.dp),color=style.third,shadowElevation=6.dp,border=androidx.compose.foundation.BorderStroke(2.dp,Color.White.copy(.85f))){Column(horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Icon(style.first,null,Modifier.size(29.dp),tint=Color.White);Spacer(Modifier.height(5.dp));Text(style.second,color=Color.White,fontSize=12.sp,fontWeight=FontWeight.Black,maxLines=1);Text(when(zone){PriorityZone.NOW->"Нужно";PriorityZone.LATER->"Желание";PriorityZone.NO->"Лишнее"},color=Color.White.copy(.78f),fontSize=10.sp)}}}
        }
