private data class FallingSaving(val id:Int,val coin:Boolean,val value:Int,val icon:String,val x:Float,val y:Float)

@Composable fun PiggyBankScreen(onBack:()->Unit,onDone:(Int)->Unit,vm:PiggyBankViewModel=hiltViewModel()){val s by vm.state.collectAsStateWithLifecycle();val percent=(s.collected.toFloat()/s.totalCoins).coerceIn(0f,1f);val falling=remember(s.level){mutableStateListOf<FallingSaving>()};var pigX by rememberSaveable(s.level){mutableFloatStateOf(.38f)};var feedback by rememberSaveable(s.level){mutableStateOf("Веди копилку пальцем. Лови монеты, а сладости и игрушки пропускай.")};val desires=listOf("🍦","🧸","🎮","🍭","⚽");GameFrame("Копилка","Лови монеты движущейся копилкой",s.level,onBack){
    LaunchedEffect(s.running,s.seconds){if(s.running){kotlinx.coroutines.delay(1000);vm.tick()}}
    LaunchedEffect(s.running){
        if(s.running){
            falling.clear();var id=0;var spawnClock=620L
            while(s.running){
                kotlinx.coroutines.delay(16);spawnClock+=16
                if(spawnClock>=760){spawnClock=0;val coin=id%10<7;val value=listOf(1,1,2,2,5,5)[(id+s.level)%6];falling+=FallingSaving(id,coin,value,desires[(id+s.level)%desires.size],((id*37+s.level*13)%82)/100f+.04f,-.14f);id++}
                val next=ArrayList<FallingSaving>(falling.size)
                falling.forEach{o->val moved=o.copy(y=o.y+.0072f+s.level*.00012f);val caught=moved.y in .72f..88f&&kotlin.math.abs((moved.x+.06f)-(pigX+.12f))<.16f;when{caught->{if(moved.coin){vm.coin(moved.value);feedback="Отлично! +${moved.value} монет в копилку."}else{vm.catchTemptation();feedback="${moved.icon} можно купить позже. Не лови предметы-искушения."}};moved.y>1.05f->{if(moved.coin)vm.missCoin()else vm.temptation()};else->next+=moved}}
                falling.clear();falling.addAll(next)
            }
        }
    }
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(7.dp)){GameStat("₽","Собрано","${s.collected}/${s.totalCoins}",Color(0xFFFFF0C9),Modifier.weight(1f));GameStat("⏱","Время","${s.seconds} с",Color(0xFFE6F0FF),Modifier.weight(1f));GameStat("✕","Искушения","${s.temptations}/3",Color(0xFFFFE2E1),Modifier.weight(1f))}
    FinnyProgressTrack(percent,Modifier.fillMaxWidth(),color=Color(0xFFFFB92F),height=13.dp)
    if(s.running){Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(28.dp),color=Color(0xFF34275C),shadowElevation=10.dp){BoxWithConstraints(Modifier.fillMaxWidth().height(345.dp).background(Brush.verticalGradient(listOf(Color(0xFF31275B),Color(0xFF67529B),Color(0xFFB99ADB)))).pointerInput(Unit){detectDragGestures(onDragStart={p->pigX=(p.x/size.width-.12f).coerceIn(0f,.76f)},onDrag={change,amount->change.consume();pigX=(pigX+amount.x/size.width).coerceIn(0f,.76f)})}){
        repeat(22){i->Box(Modifier.offset(x=((i*47)%100/100f*maxWidth.value).dp,y=((i*71)%100/100f*300).dp).size(if(i%3==0)3.dp else 2.dp).background(Color.White.copy(.65f),CircleShape))}
        falling.forEach{o->if(o.coin)Surface(Modifier.offset(x=(maxWidth-52.dp)*o.x,y=(310.dp)*o.y).size(48.dp),shape=CircleShape,color=Color(0xFFFFC83D),border=androidx.compose.foundation.BorderStroke(3.dp,Color(0xFFFFEC9A)),shadowElevation=7.dp){Box(contentAlignment=Alignment.Center){Text("${o.value}",fontSize=18.sp,fontWeight=FontWeight.Black,color=Color(0xFF805000))}}else Surface(Modifier.offset(x=(maxWidth-52.dp)*o.x,y=(310.dp)*o.y).size(48.dp),shape=RoundedCornerShape(15.dp),color=Color(0xFFFFE7F0),border=androidx.compose.foundation.BorderStroke(2.dp,Color(0xFFFF8DB4)),shadowElevation=6.dp){Box(contentAlignment=Alignment.Center){Text(o.icon,fontSize=27.sp)}}}
        Surface(Modifier.offset(x=(maxWidth-106.dp)*pigX,y=271.dp).size(width=106.dp,height=69.dp),shape=RoundedCornerShape(31.dp),color=Color(0xFFFF78A8),border=androidx.compose.foundation.BorderStroke(4.dp,Color.White),shadowElevation=10.dp){Box(contentAlignment=Alignment.Center){Text("🐷",fontSize=48.sp);Text("МОНЕТЫ",Modifier.align(Alignment.TopCenter).offset(y=(-7).dp),fontSize=8.sp,fontWeight=FontWeight.Black,color=Color.White)}}
        Text("← веди копилку пальцем →",Modifier.align(Alignment.TopCenter).padding(top=7.dp),fontSize=11.sp,color=Color.White.copy(.9f),fontWeight=FontWeight.Bold)
    }}}
    else if(s.processed==0){Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(28.dp),color=Color(0xFF34275C),shadowElevation=8.dp){Column(Modifier.fillMaxWidth().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("🐷",fontSize=86.sp);Text("Собери ${s.totalCoins} монет",fontSize=22.sp,fontWeight=FontWeight.Black,color=Color.White);Text("Можно пропустить монету, но не лови три лишних покупки.",textAlign=androidx.compose.ui.text.style.TextAlign.Center,color=Color.White.copy(.82f))}}}
    Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp),color=Color(0xFFFFE9B9),border=androidx.compose.foundation.BorderStroke(1.dp,Color(0xFFFFC45C))){Text(feedback,Modifier.padding(12.dp),fontSize=14.sp,fontWeight=FontWeight.SemiBold,color=Color(0xFF674910))}
    if(!s.running&&s.processed==0)FinnyButton("Начать игру",vm::start,modifier=Modifier.fillMaxWidth())
    if(!s.running&&s.processed>0){val success=s.collected>=s.totalCoins;Text(if(success)"Цель собрана! ${s.collected} монет в копилке." else if(s.temptations>=3)"Поймано три искушения. Пропускай игрушки и сладости." else "Время вышло: ${s.collected} из ${s.totalCoins} монет.",fontSize=17.sp,fontWeight=FontWeight.Bold,color=Color(0xFF263A65));if(success)FinnyButton("Забрать результат",{vm.finish(onDone)},modifier=Modifier.fillMaxWidth())else OutlinedButton(onClick=vm::start,modifier=Modifier.fillMaxWidth().heightIn(min=52.dp)){Text("Попробовать ещё",fontWeight=FontWeight.Bold)}}
}}

