@Composable fun GoalScreen(onBack:()->Unit,onDone:(Int)->Unit,vm:GoalGameViewModel=hiltViewModel()){val s by vm.state.collectAsStateWithLifecycle();val goalError=s.message.startsWith("Свободно")||s.message.startsWith("Чтобы")||s.message.startsWith("Сначала");if(goalError)FeedbackDialog("Проверь сумму",s.message,vm::clearMessage);GameFrame("Цель","Собери мечту по шагам",s.level,onBack){
    FinnyCard(Modifier.fillMaxWidth()){
        Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(s.goal,fontSize=22.sp,fontWeight=FontWeight.Black,color=Color(0xFF263A65));Text("${s.preview} / ${s.cost} монет",fontSize=16.sp,color=Color(0xFF667085))};Text(when(s.goal){"Игрушка"->"🧸";"Домик"->"🏠";else->"🏰"},fontSize=54.sp)}
        FinnyProgressTrack(s.preview.toFloat()/s.cost,Modifier.fillMaxWidth(),color=Color(0xFFFFB52E),height=14.dp)
        Text("До цели осталось ${(s.cost-s.preview).coerceAtLeast(0)} монет",fontWeight=FontWeight.Bold,color=Color(0xFF53627A))
    }
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(7.dp)){GameStat("💰","Доход",s.incomes.first().toString(),Color(0xFFFFF0D0),Modifier.weight(1f));GameStat("📦","Обязательно",s.expenses.first().toString(),Color(0xFFFFE8D6),Modifier.weight(1f));GameStat("✓","Свободно",s.free.toString(),Color(0xFFDFF8EE),Modifier.weight(1f))}
    Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(24.dp),color=Color.White,shadowElevation=7.dp){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Сколько положить в копилку?",fontSize=18.sp,fontWeight=FontWeight.Black,color=Color(0xFF263A65));FlowRow(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(7.dp)){s.options.forEach{a->FilterChip(selected=s.selected==a,onClick={vm.select(a)},enabled=a<=s.free,label={Text("+$a",fontWeight=FontWeight.Black)},colors=FilterChipDefaults.filterChipColors(selectedContainerColor=Color(0xFFFFD66B)))}};Text(if(s.selected>0)"После вклада останется ${s.free-s.selected} монет на текущие расходы." else "Выбери сумму, которая не превышает свободный остаток.",fontSize=14.sp,color=Color(0xFF53627A));FinnyButton("В копилку ▶",{vm.confirm{vm.finish(onDone)}},enabled=s.selected>0,modifier=Modifier.fillMaxWidth())}}
}}

@Composable fun ShopScreen(onBack:()->Unit,onDone:(Int)->Unit,vm:ShopGameViewModel=hiltViewModel()){val s by vm.state.collectAsStateWithLifecycle();val shopError=s.message.startsWith("Не хватает")||s.message.startsWith("Подумай")||s.message.startsWith("Этот товар");if(shopError)FeedbackDialog("Проверь покупку",s.message,vm::clearMessage);GameFrame("Магазин","Сначала добавь обязательный товар",s.level,onBack){
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(7.dp)){GameStat("₽","Бюджет",s.budget.toString(),Color(0xFFFFF1C9),Modifier.weight(1f));GameStat("#","В чеке",s.total.toString(),Color(0xFFE8F1FF),Modifier.weight(1f));GameStat("✓","Остаток",s.left.toString(),Color(0xFFDFF8EE),Modifier.weight(1f))}
    Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(25.dp),color=Color(0xFFF0F5FB),border=androidx.compose.foundation.BorderStroke(2.dp,Color(0xFF9CAFC8)),shadowElevation=7.dp){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("🏪 ВИТРИНА — нажми на товар",fontWeight=FontWeight.Black,color=Color(0xFF53627A));LazyRow(horizontalArrangement=Arrangement.spacedBy(9.dp)){items(s.items){i->val inCart=i in s.cart;Surface(Modifier.width(112.dp).clickable{if(inCart)vm.remove(i)else vm.add(i)},shape=RoundedCornerShape(18.dp),color=if(inCart)Color(0xFFDFF8EE) else Color.White,border=androidx.compose.foundation.BorderStroke(if(inCart)3.dp else 1.dp,if(inCart)Color(0xFF36A36F) else Color(0xFFD5DEEC)),shadowElevation=3.dp){Column(Modifier.padding(10.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(i.icon,fontSize=34.sp);Text(i.title,fontSize=12.sp,fontWeight=FontWeight.Bold,maxLines=2);Text("${i.price} мон.",fontWeight=FontWeight.Black,color=Color(0xFFB56A00));Text(if(i.required)"Нужно" else "Можно",fontSize=11.sp,color=if(i.required)Color(0xFF188653) else Color(0xFF667085))}}}}}}
    Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(25.dp),color=Color(0xFF1F3658),shadowElevation=8.dp){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){Text("🛒 ЛЕНТА КАССЫ • ${s.cart.size} товаров",color=Color.White,fontWeight=FontWeight.Black);if(s.cart.isEmpty())Box(Modifier.fillMaxWidth().height(84.dp).background(Color(0xFF10233F),RoundedCornerShape(15.dp)),contentAlignment=Alignment.Center){Text("Лента пуста — выбери товары",color=Color(0xFFB8C7DB))}else LazyRow(Modifier.fillMaxWidth().background(Color(0xFF10233F),RoundedCornerShape(15.dp)).padding(8.dp),horizontalArrangement=Arrangement.spacedBy(7.dp)){items(s.cart){i->AssistChip(onClick={vm.remove(i)},label={Text("${i.icon} ${i.price} ×")})}}}}
    Text("Сначала положи то, что питомцу необходимо. Покупки по желанию бери только на оставшиеся монеты.",fontSize=15.sp,fontWeight=FontWeight.SemiBold,color=Color(0xFF3F4E69))
    FinnyButton("Оплатить покупки",{vm.pay(onDone)},modifier=Modifier.fillMaxWidth())
}}

@OptIn(ExperimentalLayoutApi::class)
@Composable fun ChangeScreen(onBack:()->Unit,onDone:(Int)->Unit,vm:ChangeGameViewModel=hiltViewModel()){val s by vm.state.collectAsStateWithLifecycle();if(s.message.isNotEmpty())FeedbackDialog("Проверим сдачу",s.message,vm::clearMessage);GameFrame("Сдача","Собери правильную сумму",s.task,onBack){
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(7.dp)){GameStat("🏷","Цена",s.price.toString(),Color(0xFFFFE3E6),Modifier.weight(1f));GameStat("💵","Оплачено",s.paid.toString(),Color(0xFFE1F4FF),Modifier.weight(1f));GameStat("🎯","Вернуть",s.expected.toString(),Color(0xFFFFF0C9),Modifier.weight(1f))}
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){
        Surface(Modifier.weight(.8f),shape=RoundedCornerShape(20.dp),color=Color(0xFF152A48),shadowElevation=7.dp){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text("ЧЕК",color=Color(0xFF9FD8FF),fontWeight=FontWeight.Black);Text(s.itemName,color=Color.White,fontWeight=FontWeight.Bold);HorizontalDivider(color=Color.White.copy(.2f));Text("Стоимость: ${s.price}",color=Color.White);Text("К возврату: ${s.expected}",color=Color(0xFF4DDAFF),fontSize=19.sp,fontWeight=FontWeight.Black)}}
        Surface(Modifier.weight(1.2f),shape=RoundedCornerShape(20.dp),color=Color(0xFFEAF2FB),border=androidx.compose.foundation.BorderStroke(2.dp,Color(0xFF8EA5BE))){Column(Modifier.padding(12.dp)){Text("СДАЧА В ЛОТКЕ",fontWeight=FontWeight.Black,color=Color(0xFF263A65));Text("${s.total} монет",fontSize=24.sp,fontWeight=FontWeight.Black,color=Color(0xFF347FD0));Box(Modifier.fillMaxWidth().height(76.dp).background(Color(0xFF879BB2),RoundedCornerShape(14.dp)).padding(6.dp)){if(s.selected.isEmpty())Text("Набери монеты",Modifier.align(Alignment.Center),color=Color.White)else FlowRow(horizontalArrangement=Arrangement.spacedBy(4.dp)){s.selected.forEach{v->Surface(Modifier.clickable{vm.remove(v)},shape=CircleShape,color=coinColor(v),shadowElevation=3.dp){Text("$v",Modifier.padding(8.dp),fontWeight=FontWeight.Black)}}}}}}
    }
    Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(22.dp),color=Color(0xFF263A59)){Column(Modifier.padding(12.dp)){Text("МОНЕТЫ КАССЫ — нажми, чтобы добавить",color=Color.White,fontWeight=FontWeight.Black);FlowRow(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly){s.available.distinct().sorted().forEach{v->Surface(Modifier.padding(3.dp).size(52.dp).clickable{vm.add(v)},shape=CircleShape,color=coinColor(v),border=androidx.compose.foundation.BorderStroke(2.dp,Color.White),shadowElevation=5.dp){Box(contentAlignment=Alignment.Center){Text("$v",fontWeight=FontWeight.Black,fontSize=17.sp,color=Color(0xFF402D21))}}}}}}
    Text("Цена ${s.price}, оплата ${s.paid}. Набери в лотке ровно ${s.expected} монет.",fontSize=15.sp,fontWeight=FontWeight.SemiBold,color=Color(0xFF3F4E69))
    FinnyButton("✓ Выдать сдачу",{vm.check(onDone)},modifier=Modifier.fillMaxWidth())
}}

@Composable private fun GameStat(icon:String,label:String,value:String,color:Color,modifier:Modifier=Modifier){Surface(modifier.heightIn(min=68.dp),shape=RoundedCornerShape(18.dp),color=color,border=androidx.compose.foundation.BorderStroke(1.dp,Color.White),shadowElevation=4.dp){Column(Modifier.fillMaxWidth().padding(horizontal=5.dp,vertical=8.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("$icon $label",fontSize=10.sp,lineHeight=12.sp,fontWeight=FontWeight.Bold,color=Color(0xFF53627A),maxLines=2,textAlign=androidx.compose.ui.text.style.TextAlign.Center,overflow=TextOverflow.Ellipsis);Text(value,fontSize=19.sp,fontWeight=FontWeight.Black,color=Color(0xFF263A65),maxLines=1,softWrap=false)}}}
@Composable private fun FinnySpeechCard(text:String){Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(21.dp),color=Color(0xFFFFE9B9),border=androidx.compose.foundation.BorderStroke(2.dp,Color(0xFFFFC45C))){Row(Modifier.padding(13.dp),verticalAlignment=Alignment.CenterVertically){Text("🐾",fontSize=29.sp);Spacer(Modifier.width(9.dp));Text(text,Modifier.weight(1f),fontSize=15.sp,fontWeight=FontWeight.SemiBold,color=Color(0xFF674910))}}}
private fun coinColor(value:Int)=when(value){1->Color(0xFFF4B84E);2->Color(0xFFFFD34D);5->Color(0xFFE7A92E);10->Color(0xFFFF9A66);20->Color(0xFF79A8FF);else->Color(0xFFF062A6)}
